import { readFileSync } from 'node:fs'
import { join } from 'node:path'
import { app } from 'electron'

import { parseBuildInfo, type BuildInfo } from '@shared/buildInfo'

/**
 * This build's info, from `resources/build-info.json` (inside the app bundle when packaged;
 * generated by `scripts/build-info.mjs` for `npm run dev` / `npm run build`). Falls back to the
 * package version if the file is missing, e.g. when electron-vite is run directly.
 */
export function loadBuildInfo(): BuildInfo {
  try {
    const raw: unknown = JSON.parse(
      readFileSync(join(app.getAppPath(), 'resources', 'build-info.json'), 'utf-8')
    )
    const info = parseBuildInfo(raw)
    if (info) return info
    console.error('resources/build-info.json is not valid build info')
  } catch (error) {
    console.error(`Could not read resources/build-info.json: ${String(error)}`)
  }
  return {
    version: app.getVersion(),
    buildNumber: null,
    commit: null,
    dirty: false,
    buildDate: null
  }
}
